import torch


def gen_inputs(ctx, device):
    n_shape = ctx["n__shape"]
    n = torch.randint(0, 11, n_shape, dtype=torch.int32, device=device)
    return {"n": n}


def run_correctness(x, n):
    output = torch.special.shifted_chebyshev_polynomial_w(
        x.float(), n.float()
    )
    return output.to(x.dtype)


def run(x, n):
    return torch.special.shifted_chebyshev_polynomial_w(x, n)
